-- ============================================================
-- Butir DUMMY untuk D-02, D-03, dan D-08 — supaya sistemnya bisa dilihat
-- berjalan pada lebih dari satu topik
--
-- SELURUH ISI MIGRASI INI BUTIR SEMENTARA. Ia ditulis untuk MENGUJI MESINNYA,
-- bukan untuk mengajar anak. Sebelum aplikasinya dipublikasikan ke murid,
-- isinya harus diganti butir yang ditulis dan diverifikasi sungguhan — atau
-- ketiga topiknya dinonaktifkan lagi.
--
-- Semuanya bisa dicabut dengan dua perintah, karena ketiga topik ini tidak
-- punya butir lain sama sekali:
--
--   delete from question_bank_items where topik_id in ('D-02','D-03','D-08');
--   update topik set aktif = false where id in ('D-02','D-03','D-08');
--
-- KENAPA TIGA TOPIK INI, bukan yang lain. Bukan pilihan acak — ketiganya
-- membuka pengujian yang mustahil dilakukan dengan D-01 sendirian:
--
--   * D-01 -> D-02 -> D-03 adalah rantai prasyarat sepanjang TIGA. Dokumen
--     Retest Terjadwal Bagian 7 poin 4c menuntut pembuktian bahwa kegagalan
--     retest menjalar berjenjang (A gagal -> B ditandai -> B gagal verifikasi
--     -> C ikut ditandai) TANPA perhitungan transitif terpisah. Dengan satu
--     topik aktif, klaim inti desain itu tidak pernah bisa diuji.
--   * D-02 juga membuka `siap_dikerjakan` yang sungguhan: hari ini seluruh
--     topik selain D-01 berstatus `terkunci`, jadi transisi terkunci ->
--     siap_dikerjakan (FR13) belum pernah terjadi pada data nyata.
--   * D-08 bertanda EKSTRA WAJIB dan berprasyarat D-02. Ia satu-satunya jalan
--     menguji cabang `interval_awal_topik` yang memberi 7 hari alih-alih 14
--     — cabang yang sampai sekarang tidak pernah dieksekusi.
--
-- JAWABANNYA DIHITUNG, BUKAN DIKETIK. Dummy boleh dangkal, tapi kunci yang
-- salah membuat seluruh pengujian skoring tidak berarti apa-apa: paket akan
-- "gagal" karena kuncinya keliru, bukan karena mesinnya keliru, dan yang
-- ditemukan bukan bug melainkan kebisingan. Tiap butir di bawah dihasilkan
-- templat yang menghitung jawabannya sendiri, lalu diperiksa ulang bahwa
-- kuncinya ada di antara opsinya dan tidak ada dua opsi yang kembar.
--
-- DISTRAKTORNYA TETAP MISKONSEPSI, meski dummy. Ongkosnya nyaris nol —
-- templatnya sama saja — dan hasilnya bisa dipakai memeriksa apakah pola
-- jawaban yang terbaca di rapor tutor memang masuk akal. Angka acak akan
-- menghasilkan sebaran yang tidak bisa dibedakan dari kerusakan.
--
-- Sesudah butirnya masuk, `semai_paket_topik` menyusun paketnya dan ketiga
-- topiknya diaktifkan — tanpa keduanya, butir yang mendarat di sini tidak
-- mengubah satu pun yang terlihat.
--
-- Jalankan SESUDAH 168.
-- ============================================================

do $$
declare
  v_penulis uuid;
  v_id uuid;
  v_butir jsonb;
  v_topik text;
begin
  if exists (select 1 from question_bank_items where topik_id in ('D-02','D-03','D-08')) then
    raise notice 'D-02/D-03/D-08 sudah punya butir — dilewati.';
    return;
  end if;

  select id into v_penulis from profiles where role = 'admin' order by created_at limit 1;

