$butir$)
  loop
    insert into question_bank_items (
      created_by, type, prompt, options, correct_answer, weight,
      bloom_level, status_verifikasi, penjelasan_per_opsi,
      elemen_proses, sumber_pembuatan, peruntukan, topik_id
    ) values (
      v_penulis,
      v_butir ->> 'type',
      v_butir ->> 'prompt',
      case when jsonb_typeof(v_butir -> 'choices') = 'array'
        then jsonb_build_object('choices', v_butir -> 'choices')
        else null end,
      case when (v_butir ->> 'type') = 'short_answer'
        then jsonb_build_array(v_butir ->> 'correct')
        else to_jsonb(v_butir ->> 'correct') end,
      1,
      (v_butir ->> 'bloom')::smallint,
      'aktif',
      case when jsonb_array_length(coalesce(v_butir -> 'why', '[]'::jsonb)) > 0 then (
        select jsonb_object_agg((i - 1)::text, w)
        from jsonb_array_elements_text(v_butir -> 'why') with ordinality as t(w, i)
      ) else null end,
      array['penalaran']::text[],
      'ai_generated_verified',
      v_butir ->> 'peruntukan',
      v_butir ->> 'topik'
    )
    returning id into v_id;

    -- Butir probe TIDAK jadi anggota paket (trigger migrasi 164 menolaknya),
    -- jadi ia hanya masuk kolam probenya sendiri.
    if (v_butir ->> 'peruntukan') = 'probe' then
      insert into item_probe (topik_id, question_bank_item_id)
      values (v_butir ->> 'topik', v_id);
    end if;
  end loop;

  foreach v_topik in array array['D-02','D-03','D-08'] loop
    perform semai_paket_topik(v_topik);
  end loop;

  -- Dibuka untuk murid. Tanpa ini `topik_tersedia` tetap menyembunyikannya.
  update topik set aktif = true where id in ('D-02','D-03','D-08');
end;
$$;

notify pgrst, 'reload schema';
